Scheme.LaunchImageStyle:
LaunchImage {
  background-color: #0f0f0f;
}
QLabel {
  /* CP11 T7: ANDY'S MIXXX lockup on the launch splash (drawn at its
     native 158x24, centered in the label box). */
  image: url(skins:LateNight/palemoon/style/andys_mixxx_logo_small.svg);
  padding: 0;
  margin: 0px 2px 0px 2px;
  border: none;
  min-width: 160px;
  max-width: 160px;
  min-height: 40px;
  max-height: 40px;
}
QProgressBar {
  background: url(skins:LateNight/palemoon/style/progressbar_bg.svg);
  border: none;
  min-width: 164px;
  max-width: 164px;
  min-height: 5px;
  max-height: 5px;
}
QProgressBar::chunk {
  background: url(skins:LateNight/palemoon/style/progressbar.svg);
}

LaunchImage {
  background-color: #1e1e1e;
}
QLabel {
  /* CP11 T7: ANDY'S MIXXX lockup on the launch splash (drawn at its
     native 158x24, centered in the label box). */
  image: url(skins:LateNight/classic/style/andys_mixxx_logo_small.svg);
  padding: 0;
  margin: 0px 2px 0px 2px;
  border: none;
  min-width: 162px;
  max-width: 162px;
  min-height: 42px;
  max-height: 42px;
}
QProgressBar {
  background: url(skins:LateNight/classic/style/progressbar_bg.svg);
  border: none;
  min-width: 160px;
  max-width: 160px;
  min-height: 5px;
  max-height: 5px;
}
QProgressBar::chunk {
  background: url(skins:LateNight/classic/style/progressbar.svg);
}
